using UnityEngine;using UnityEngine.AI;using System.IO;using System.Collections;using System.Linq;
public class TerracedVillageProbe:MonoBehaviour {
 public string phase="before";
 IEnumerator Start(){string e="Evidence/terraced-village-20261030/";int oldV=QualitySettings.vSyncCount,oldTarget=Application.targetFrameRate;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;var movement=GetComponent<DemoMovement>();var cam=movement.viewCamera;var follow=cam.GetComponent<DemoCamera>();var agent=GetComponent<NavMeshAgent>();string s="Unity="+Application.unityVersion+" editor="+Application.isEditor+" resolution="+Screen.width+"x"+Screen.height+"\n";
 foreach(var spot in new[]{new Vector3(-30,0,-8),new Vector3(-9,0,-5),new Vector3(16,0,-4)}){NavMesh.SamplePosition(spot,out var h,5,NavMesh.AllAreas);agent.Warp(h.position);yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+phase+"_view"+spot.x+".png"));yield return new WaitForSeconds(.2f);int frames=0;float total=0;float until=Time.realtimeSinceStartup+3;while(Time.realtimeSinceStartup<until){yield return null;total+=Time.unscaledDeltaTime;frames++;}s+="view="+spot+" frames="+frames+" elapsed="+total+" fps="+(frames/total)+" meanMs="+(total/Mathf.Max(1,frames)*1000)+"\n";}
 if(phase=="after"){foreach(var clue in Resources.FindObjectsOfTypeAll<DemoInteractable>().Where(c=>c.gameObject.scene==gameObject.scene)){bool sample=NavMesh.SamplePosition(clue.transform.position,out var dest,4,NavMesh.AllAreas);var path=new NavMeshPath();bool ok=sample&&NavMesh.CalculatePath(agent.transform.position,dest.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;s+="target="+clue.clueId+" completePath="+ok+"\n";}agent.SetDestination(new Vector3(-9,agent.transform.position.y,-5));yield return new WaitForSeconds(1);s+="agentOnNavMesh="+agent.isOnNavMesh+" movementPath="+agent.pathStatus+" velocity="+agent.velocity+"\n";}
 if(phase=="after"){
 var spawn=new Vector3(-42.5f,0,-5.6f);NavMesh.SamplePosition(spawn,out var spawnHit,5,NavMesh.AllAreas);agent.Warp(spawnHit.position);var roadEnd=new Vector3(-2.5f,0,-6.04f);NavMesh.SamplePosition(roadEnd,out var endHit,5,NavMesh.AllAreas);agent.SetDestination(endHit.position);float low=transform.position.y,high=low;float walkUntil=Time.time+14;while(Time.time<walkUntil&&(agent.pathPending||agent.remainingDistance>.5f)){yield return null;low=Mathf.Min(low,transform.position.y);high=Mathf.Max(high,transform.position.y);}s+="roadWalkRemaining="+agent.remainingDistance+" heightMin="+low+" heightMax="+high+" path="+agent.pathStatus+"\n";
 if(follow)follow.enabled=false;
 var lights=FindObjectsOfType<Light>().Where(l=>l.name=="Interior window outward spill").ToArray();
 foreach(string id in new[]{"B01","B02","B10"}){var choices=lights.Where(l=>l.transform.parent.name.StartsWith(id)).ToArray();if(choices.Length==0)continue;var door=choices[0].transform.parent.Find("door");var chosen=choices.OrderByDescending(l=>Vector3.Dot(l.transform.forward,door.forward)).First();var face=chosen.transform.position+chosen.transform.forward*.18f;var normal=chosen.transform.forward;normal.y=0;normal.Normalize();var at=face+normal*4.5f+Vector3.Cross(Vector3.up,normal)*1.1f+Vector3.up*1.2f;cam.transform.position=at;cam.transform.LookAt(face);yield return new WaitForSeconds(.8f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"window_"+id+".png"));yield return new WaitForSeconds(.2f);var v=chosen.GetComponent<VolumetricAdditionalLight>();var clear=chosen.GetComponent<SettlementFogLight>();s+="window="+id+" position="+chosen.transform.position+" scatter="+v.Scattering+" fogStrength="+clear.strength+"\n";
 if(id=="B02"){float saved=v.Scattering;v.Scattering=0;yield return new WaitForSeconds(.4f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"window_B02_volume_off.png"));yield return new WaitForSeconds(.2f);v.Scattering=saved;chosen.enabled=false;FindObjectOfType<SettlementFogManager>().Upload(1);s+="windowDisabledFogStrength="+clear.strength+"\n";chosen.enabled=true;FindObjectOfType<SettlementFogManager>().Upload(1);s+="windowRestoredFogStrength="+clear.strength+"\n";}}
 cam.transform.position=new Vector3(-12,19,-26);cam.transform.LookAt(new Vector3(-12,1.6f,-2));yield return new WaitForSeconds(.8f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"village_overview.png"));yield return new WaitForSeconds(.2f);cam.transform.position=new Vector3(-30,5,-12);cam.transform.LookAt(new Vector3(-10,2.3f,-5));yield return new WaitForSeconds(.8f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"road_relief.png"));yield return new WaitForSeconds(.2f);if(follow)follow.enabled=true;
 }
 File.WriteAllText(e+phase+"_playmode.txt",s);QualitySettings.vSyncCount=oldV;Application.targetFrameRate=oldTarget;}
}
